20	func getGatewayAppDataDir() string {
21		if explicit := os.Getenv("KNIRV_APP_DATA_DIR"); explicit != "" {
22			return explicit
23		}
24		if err := os.MkdirAll("/var/lib/knirvserver", 0755); err == nil {
25			return "/var/lib/knirvserver"
26		}
27		if home, err := os.UserHomeDir(); err == nil {
28			return filepath.Join(home, ".local", "share", "knirvserver")
29		}
30		return "data"
31	}
32	
33	// killStaleGateway sends SIGTERM (then SIGKILL after 2 s) to any running
34	// processes whose executable matches the given binary name. This prevents
35	// port-conflict crashes when the parent process was previously killed
36	// without triggering the normal Stop() path.
37	func killStaleGateway(binaryPath string) {
38		if binaryPath == "" {
39			return
40		}
41		binaryName := filepath.Base(binaryPath)
42		// SIGTERM first
43		if cmd := exec.Command("pkill", "-TERM", "-x", binaryName); cmd.Run() == nil {
44			time.Sleep(1 * time.Second)
45		}
46		// SIGKILL any survivors
47		exec.Command("pkill", "-KILL", "-x", binaryName).Run() //nolint:errcheck
48	}
49	
50	// waitForPortFree blocks until the given TCP port is no longer occupied or
51	// the deadline is reached. Returns true if the port is free.
52	func waitForPortFree(port int, deadline time.Duration) bool {
53		end := time.Now().Add(deadline)
54		for time.Now().Before(end) {
55			ln, err := net.Listen("tcp", fmt.Sprintf(":%d", port))
56			if err == nil {
57				ln.Close()
58				return true
59			}
60			time.Sleep(200 * time.Millisecond)
61		}
62		return false
63	}
64	
