140	
141	func NewManager(cfg *ManagerConfig, logger *zap.Logger) *Manager {
142		if cfg.StartTimeout == 0 {
143			cfg.StartTimeout = 30 * time.Second
144		}
145		if cfg.StopTimeout == 0 {
146			cfg.StopTimeout = 10 * time.Second
147		}
148	
149		var baseURL string
150		if cfg.SocketPath != "" {
151			baseURL = "http://localhost"
152		} else {
153			baseURL = fmt.Sprintf("http://localhost:%d", cfg.Port)
154			if cfg.Port == 0 {
155				baseURL = "http://localhost:8080"
156			}
157		}
158	
159		m := &Manager{
160			config:  cfg,
161			logger:  logger,
162			baseURL: baseURL,
163			client: &http.Client{
164				Timeout: 10 * time.Second,
165			},
166		}
167	
168		if cfg.SocketPath != "" {
169			m.client.Transport = &http.Transport{
170				DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
171					return net.Dial("unix", cfg.SocketPath)
172				},
173			}
174		}
175	
176		return m
