178	
179	func (m *Manager) Start(ctx context.Context) error {
180		m.mu.Lock()
181		defer m.mu.Unlock()
182	
183		if m.running {
184			m.logger.Info("KNIRVGATEWAY already running")
185			return nil
186		}
187	
188		if m.config.BinaryPath == "" {
189			m.config.BinaryPath = "./knirvgateway"
190		}
191	
192		// Resolve the binary path, trying several candidate locations.
193		resolved, err := resolveBinaryPath(m.config.BinaryPath)
194		if err != nil {
195			return fmt.Errorf("KNIRVGATEWAY binary not found (tried %s and fallbacks): %w", m.config.BinaryPath, err)
196		}
197		m.config.BinaryPath = resolved
198	
199		// Pre-flight: if a healthy gateway is already listening (stale process from a
200		// previous run), adopt it rather than starting a duplicate and hitting a port
201		// conflict on the tunnel control port (3003).
202		preflightClient := &http.Client{
203			Timeout:   3 * time.Second,
204			Transport: m.client.Transport,
205		}
206		if resp, err := preflightClient.Get(fmt.Sprintf("%s/health", m.baseURL)); err == nil {
207			resp.Body.Close()
208			if resp.StatusCode == http.StatusOK {
209				m.logger.Info("Adopting existing healthy KNIRVGATEWAY process (skipping new spawn)")
210				m.running = true
211				return nil
212			}
213		}
214	
215		// Existing process is unhealthy or absent — kill any stale instance so the
216		// ports (especially the tunnel control port 3003) are free before we start.
217		m.logger.Info("Killing any stale KNIRVGATEWAY processes", zap.String("binary", m.config.BinaryPath))
218		killStaleGateway(m.config.BinaryPath)
219	
220		// Wait for the tunnel control port to be released before spawning the new
221		// binary. This closes the race window between kill and exec.
222		ctrlPort := 13003
223		if m.config.Ports != nil && m.config.Ports.TunnelCtrl != 0 {
224			ctrlPort = m.config.Ports.TunnelCtrl
225		}
226		if !waitForPortFree(ctrlPort, 5*time.Second) {
227			m.logger.Warn("Tunnel control port still occupied after kill — proceeding anyway",
228				zap.Int("port", ctrlPort))
229		}
230	
231		m.logger.Info("Starting KNIRVGATEWAY",
232			zap.String("binary", m.config.BinaryPath),
233			zap.String("socketPath", m.config.SocketPath))
234	
235		env := os.Environ()
236		backendPort := m.config.BackendAPIPort
237		if backendPort <= 0 {
238			backendPort = 9081
239		}
240		env = append(env,
241			fmt.Sprintf("KNIRV_BACKEND_API_URL=http://127.0.0.1:%d", backendPort),
242			fmt.Sprintf("KNIRV_CHAIN_ID=%s", m.config.ChainID),
243			"AUTO_OPEN_BROWSER=false",
244			"TURN_SERVER_ENABLED=true",
245			fmt.Sprintf("TURN_SERVER_UDP_PORT=%d", m.config.Ports.TurnUDP),
246			fmt.Sprintf("TURN_SERVER_TCP_PORT=%d", m.config.Ports.TurnTCP),
247			fmt.Sprintf("TURN_SERVER_API_PORT=%d", m.config.Ports.TurnAPI),
248			fmt.Sprintf("TURN_SERVER_AUTH_SECRET=%s", m.config.AuthSecret),
249			"TURN_SERVER_REALM=knirvgateway.local",
250			fmt.Sprintf("TURN_SERVER_MINER_ADDRESS=%s", m.config.MinerAddress),
251			"TUNNEL_REGISTRY_ENABLED=true",
252			fmt.Sprintf("TUNNEL_REGISTRY_HTTP_PORT=%d", m.config.Ports.TunnelHTTP),
253			fmt.Sprintf("TUNNEL_REGISTRY_CONTROL_PORT=%d", m.config.Ports.TunnelCtrl),
254			fmt.Sprintf("TUNNEL_REGISTRY_PUBLIC_RELAY_PORT=%d", m.config.Ports.TunnelRelay),
255			fmt.Sprintf("TUNNEL_REGISTRY_STUN_PORT=%d", m.config.Ports.TunnelSTUN),
256			fmt.Sprintf("DATABASE_PATH=%s", m.config.DBPath),
257		)
