309	// resolveBinaryPath returns the first path where the knirvgateway binary exists.
310	// Priority: KNIRV_GATEWAY_BINARY_PATH env var → configured path → standard fallbacks.
311	func resolveBinaryPath(configured string) (string, error) {
312		var candidates []string
313	
314		// Highest priority: explicit env var set by the launcher (main.go).
315		if envPath := os.Getenv("KNIRV_GATEWAY_BINARY_PATH"); envPath != "" {
316			candidates = append(candidates, envPath)
317		}
318	
319		if extractedPath, err := ExtractEmbeddedBinary(""); err == nil {
320			candidates = append(candidates, extractedPath)
321		}
322	
323		// Try executable directory first for embedded binaries
324		if exe, err := os.Executable(); err == nil {
325			exeDir := filepath.Dir(exe)
326			candidates = append(candidates,
327				filepath.Join(exeDir, "knirvgateway"),
328				filepath.Join(exeDir, "bin", "knirvgateway"),
329			)
330		}
331	
332		// Embedded directory (extracted binaries)
333		embeddedDir := filepath.Join(getGatewayAppDataDir(), "bin")
334		candidates = append(candidates,
335			filepath.Join(embeddedDir, "knirvgateway"),
336			filepath.Join(embeddedDir, "..", "bin", "knirvgateway"),
337		)
338	
339		candidates = append(candidates, configured)
340	
341		// Common fallback locations relative to the working directory.
342		dir, _ := os.Getwd()
343		candidates = append(candidates,
344			filepath.Join(dir, "bin", "knirvgateway"),
345			filepath.Join(dir, "..", "bin", "knirvgateway"),
346			filepath.Join(filepath.Dir(configured), "bin", "knirvgateway"),
347		)
348	
349		for _, p := range candidates {
350			if _, err := os.Stat(p); err == nil {
351				return p, nil
352			}
353		}
354	
355		return "", fmt.Errorf("binary not found in any candidate location")
356	}
357	
358	func (m *Manager) waitForHealth(ctx context.Context) error {
359		deadline, cancel := context.WithTimeout(ctx, m.config.StartTimeout)
360		defer cancel()
361	
362		ticker := time.NewTicker(500 * time.Millisecond)
363		defer ticker.Stop()
364	
365		healthURL := fmt.Sprintf("%s/health", m.baseURL)
366	
367		for {
368			select {
369			case <-deadline.Done():
370				return fmt.Errorf("timeout waiting for KNIRVGATEWAY health check")
371			case <-ticker.C:
372				resp, err := m.client.Get(healthURL)
373				if err == nil {
374					resp.Body.Close()
375					if resp.StatusCode == http.StatusOK {
376						m.logger.Debug("KNIRVGATEWAY health check passed")
377						return nil
378					}
379				}
380			}
381		}
382	}
383	
384	func (m *Manager) Stop(ctx context.Context) error {
385		m.mu.Lock()
386		defer m.mu.Unlock()
387	
388		if !m.running || m.cmd == nil || m.cmd.Process == nil {
389			return nil
390		}
391	
392		m.logger.Info("Stopping KNIRVGATEWAY")
393	
394		if err := m.cmd.Process.Signal(syscall.SIGTERM); err != nil {
395			m.logger.Warn("Failed to send SIGTERM, forcing kill",
396				zap.Error(err))
397			m.cmd.Process.Kill()
398		}
399	
400		done := make(chan error, 1)
401		go func() {
402			done <- m.cmd.Wait()
403		}()
404	
405		select {
406		case err := <-done:
407			m.running = false
408			if err != nil {
409				m.logger.Info("KNIRVGATEWAY stopped", zap.Error(err))
410			} else {
411				m.logger.Info("KNIRVGATEWAY stopped gracefully")
412			}
413			return nil
414		case <-time.After(m.config.StopTimeout):
415			m.logger.Warn("Timeout waiting for graceful shutdown, forcing kill")
416			m.cmd.Process.Kill()
417			m.running = false
418			return fmt.Errorf("forced shutdown after timeout")
419		}
420	}
421	
422	func (m *Manager) IsRunning() bool {
423		m.mu.RLock()
424		defer m.mu.RUnlock()
425		return m.running
426	}
427	
428	func (m *Manager) GetBaseURL() string {
429		return m.baseURL
430	}
431	
432	func (m *Manager) GetConfig() *ManagerConfig {
433		return m.config
434	}
435	
436	func (m *Manager) HealthCheck(ctx context.Context) error {
437		resp, err := m.client.Get(fmt.Sprintf("%s/health", m.baseURL))
438		if err != nil {
439			return fmt.Errorf("health check failed: %w", err)
440		}
441		defer resp.Body.Close()
442	
443		if resp.StatusCode != http.StatusOK {
444			return fmt.Errorf("health check returned status %d", resp.StatusCode)
445		}
446	
447		return nil
448	}
449	
450	func (m *Manager) GetTurnStatus(ctx context.Context) (*TurnServerStatus, error) {
451		url := fmt.Sprintf("http://localhost:%d/api/turn/status", m.config.Ports.TurnAPI)
452		resp, err := m.client.Get(url)
453		if err != nil {
454			return nil, fmt.Errorf("failed to get TURN status: %w", err)
455		}
456		defer resp.Body.Close()
457	
