1	package runtime
2	
3	import (
4		"embed"
5		"fmt"
6		"io/fs"
7		"os"
8		"path/filepath"
9		"strings"
10		"sync"
11	
12		"go.uber.org/zap"
13	)
14	
15	// Runtime manages the runtime directory for extracted files
16	type Runtime struct {
17		BaseDir           string
18		NetworkWebsiteDir string
19		WebGUIStaticDir   string
20		OracleBinaryPath  string
21		logger            *zap.Logger
22		mu                sync.Mutex
23		extracted         bool
24	
25		// Embedded assets
26		webGUIFS         embed.FS
27		networkWebsiteFS embed.FS
28		oracleBinary     []byte
29	}
30	
31	// NewRuntime creates a new runtime manager with embedded assets
32	func NewRuntime(logger *zap.Logger, webGUIFS embed.FS, networkWebsiteFS embed.FS, oracleBinary []byte) (*Runtime, error) {
33		var baseDir string
34	
35		if appDataDir := os.Getenv("KNIRV_APP_DATA_DIR"); appDataDir != "" {
36			baseDir = filepath.Join(appDataDir, "knirvgateway", "runtime")
37		} else if err := os.MkdirAll("/var/lib/knirvserver/knirvgateway/runtime", 0750); err == nil {
38			baseDir = "/var/lib/knirvserver/knirvgateway/runtime"
39		} else if homeDir, homeErr := os.UserHomeDir(); homeErr == nil {
40			baseDir = filepath.Join(homeDir, ".local", "share", "knirvserver", "knirvgateway", "runtime")
41		} else {
42			logger.Warn("Could not determine runtime data directory, falling back to system temp", zap.Error(err))
43			baseDir = filepath.Join(os.TempDir(), "knirvgateway-runtime")
44		}
45	
46		// Ensure base directory exists with proper permissions
47		if err := os.MkdirAll(baseDir, 0750); err != nil {
48			return nil, fmt.Errorf("failed to create runtime base directory: %w", err)
49		}
50	
51		r := &Runtime{
52			BaseDir:           baseDir,
53			NetworkWebsiteDir: filepath.Join(baseDir, "network-website"),
54			WebGUIStaticDir:   filepath.Join(baseDir, "webgui-static"),
55			OracleBinaryPath:  filepath.Join(baseDir, "knirv-oracle"),
56			logger:            logger,
57			webGUIFS:          webGUIFS,
58			networkWebsiteFS:  networkWebsiteFS,
59			oracleBinary:      oracleBinary,
60		}
61	
62		return r, nil
63	}
64	
65	// Setup extracts all embedded files to the runtime directory
66	func (r *Runtime) Setup() error {
67		r.mu.Lock()
68		defer r.mu.Unlock()
69	
70		if r.extracted {
71			r.logger.Info("Runtime already setup")
72			return nil
73		}
74	
75		r.logger.Info("Setting up runtime environment", zap.String("baseDir", r.BaseDir))
76	
77		// Clean existing directory if it exists
78		if err := os.RemoveAll(r.BaseDir); err != nil {
79			r.logger.Warn("Failed to clean existing runtime directory", zap.Error(err))
80		}
81	
82		// Create base directory
83		if err := os.MkdirAll(r.BaseDir, 0755); err != nil {
84			return fmt.Errorf("failed to create runtime directory: %w", err)
85		}
86	
87		// Extract explorer static files.
88		r.logger.Info("Extracting embedded explorer static files...")
89		if err := r.extractWebGUI(r.WebGUIStaticDir); err != nil {
90			return fmt.Errorf("failed to extract explorer static files: %w", err)
91		}
92	
93		// Network-website extraction has been disabled.
94		// The gateway now serves minimal routing; external websites are handled separately.
95		// If on-disk network-website directory exists, use it for backward compatibility.
96		if sourceDir := r.resolveNetworkWebsiteSourceDir(); sourceDir != "" {
97			r.NetworkWebsiteDir = sourceDir
98			r.logger.Info("Using on-disk network-website directory", zap.String("networkWebsiteDir", r.NetworkWebsiteDir))
99		} else {
100			// No extraction - use empty placeholder or default path
101			r.logger.Info("Network-website extraction disabled; no on-disk directory found", zap.String("networkWebsiteDir", r.NetworkWebsiteDir))
102		}
103	
104		// Oracle binary extraction removed (oracle moved to KNIRVSERVER)
105		// No longer extracting knirv-oracle binary
106	
107		r.extracted = true
108		r.logger.Info("Runtime setup complete",
109			zap.String("explorerStaticDir", r.WebGUIStaticDir),
110			zap.String("networkWebsiteDir", r.NetworkWebsiteDir),
111		)
112	
113		return nil
114	}
115	
116	// extractWebGUI extracts only the explorer static files to a target directory.
117	func (r *Runtime) extractWebGUI(targetDir string) error {
118		r.logger.Info("Extracting embedded explorer static files", zap.String("target", targetDir))
119	
120		// Create target directory
121		if err := os.MkdirAll(targetDir, 0755); err != nil {
122			return fmt.Errorf("failed to create target directory: %w", err)
123		}
124	
125		// Extract only explorer files from the embedded webgui bundle.
126		err := fs.WalkDir(r.webGUIFS, ".", func(path string, d fs.DirEntry, err error) error {
127			if err != nil {
128				return err
129			}
130	
131			// Get relative path
132			relPath, err := filepath.Rel(".", path)
133			if err != nil {
134				return err
135			}
136	
137			// Skip the root "." directory itself, but allow walking into it
138			if relPath == "." {
139				return nil
140			}
141	
142			// Skip everything except explorer files.
143			if !strings.HasPrefix(relPath, "webgui") {
144				if d.IsDir() {
145					return fs.SkipDir
146				}
147				return nil
148			}
149	
150			// Only extract the built explorer files from out/.
151			// Allow descending into "webgui" and "webgui/out" directories, skip everything else.
152			if d.IsDir() {
153				// Allow the embedded explorer root directory.
154				if relPath == "webgui" {
155					return nil
156				}
157				// Allow webgui/out and its subdirectories.
158				if strings.HasPrefix(relPath, "webgui/out") {
159					// Create the directory in the target location
160					staticPath := strings.TrimPrefix(relPath, "webgui/out/")
161					staticPath = strings.TrimPrefix(staticPath, "/")
162					targetPath := filepath.Join(targetDir, staticPath)
163	
164					if err := os.MkdirAll(targetPath, 0755); err != nil {
165						return fmt.Errorf("failed to create directory %s: %w", targetPath, err)
166					}
167					return nil
168				}
169				// Skip all other embedded source directories (src, node_modules, etc.).
170				return fs.SkipDir
171			}
172	
173			// Skip files that are not in the built explorer bundle.
174			if !strings.HasPrefix(relPath, "webgui/out/") {
175				return nil
176			}
177	
178			// Determine target path - remove the "webgui/out" prefix
179			staticPath := strings.TrimPrefix(relPath, "webgui/out/")
180			// If still has leading slash after trim (shouldn't happen but be safe), remove it
181			staticPath = strings.TrimPrefix(staticPath, "/")
182			targetPath := filepath.Join(targetDir, staticPath)
183	
184			if d.IsDir() {
185				// Create directory
186				return os.MkdirAll(targetPath, 0755)
187			}
188	
189			// Read embedded file
190			data, err := fs.ReadFile(r.webGUIFS, path)
191			if err != nil {
192				return fmt.Errorf("failed to read embedded file %s: %w", path, err)
193			}
194	
