1	package webgui
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"io"
7		"net/http"
8	
9		"github.com/KNIRV/KNIRV_NETWORK/KNIRVGATEWAY/internal/config"
10		"github.com/gorilla/mux"
11		"go.uber.org/zap"
12	)
13	
14	// Handler handles explorer API requests.
15	type Handler struct {
16		config     *config.Config
17		logger     *zap.Logger
18		httpClient *http.Client
19	}
20	
21	// NewHandler creates a new explorer handler.
22	func NewHandler(cfg *config.Config, logger *zap.Logger) *Handler {
23		return &Handler{
24			config:     cfg,
25			logger:     logger,
26			httpClient: &http.Client{},
27		}
28	}
29	
30	// RegisterRoutes registers the explorer API routes.
31	func (h *Handler) RegisterRoutes(r *mux.Router) {
32		// API routes that proxy to backend
33		r.HandleFunc("/api/objects", h.handleObjects).Methods("GET")
34		r.HandleFunc("/api/transactions", h.handleTransactions).Methods("GET")
35		r.HandleFunc("/api/blocks", h.handleBlocks).Methods("GET")
36		r.HandleFunc("/api/assets", h.handleAssets).Methods("GET")
37		r.HandleFunc("/api/view/{id}", h.handleView).Methods("GET")
38	}
39	
40	// getBackendURL returns the backend URL for proxying requests
41	func (h *Handler) getBackendURL() string {
42		// Use payment oracle as backend (default port 3001)
43		return fmt.Sprintf("http://localhost:%d", h.config.PaymentGatewayPort)
44	}
45	
46	// proxyRequest proxies a request to the backend
47	func (h *Handler) proxyRequest(w http.ResponseWriter, r *http.Request, endpoint string) {
48		backendURL := h.getBackendURL() + endpoint
49	
50		h.logger.Debug("Proxying request",
51			zap.String("method", r.Method),
52			zap.String("url", r.URL.Path),
53			zap.String("backend", backendURL),
54		)
55	
56		// Create request to backend
57		req, err := http.NewRequest(r.Method, backendURL, r.Body)
58		if err != nil {
59			h.logger.Error("Failed to create backend request", zap.Error(err))
60			http.Error(w, "Internal server error", http.StatusInternalServerError)
61			return
62		}
63	
64		// Copy headers
65		for key, values := range r.Header {
66			for _, value := range values {
67				req.Header.Add(key, value)
68			}
69		}
70	
71		// Make request to backend
72		resp, err := h.httpClient.Do(req)
73		if err != nil {
74			h.logger.Error("Failed to proxy request to backend",
75				zap.String("backend", backendURL),
76				zap.Error(err),
77			)
78	
79			// Return mock data as fallback (similar to TypeScript implementation)
80			h.returnMockData(w, endpoint)
81			return
82		}
83		defer resp.Body.Close()
84	
85		// Copy response headers
86		for key, values := range resp.Header {
87			for _, value := range values {
88				w.Header().Add(key, value)
89			}
90		}
91	
92		// Set status code
93		w.WriteHeader(resp.StatusCode)
94	
95		// Copy response body
96		io.Copy(w, resp.Body)
97	}
98	
99	// returnMockData returns mock data when backend is unavailable
100	func (h *Handler) returnMockData(w http.ResponseWriter, endpoint string) {
101		w.Header().Set("Content-Type", "application/json")
102	
103		switch endpoint {
104		case "/api/objects":
105			mockData := []map[string]interface{}{
106				{"id": "mock-1", "name": "Mock Cube", "object_type": "glb"},
107				{"id": "mock-2", "name": "Mock Sphere", "object_type": "glb"},
108			}
109			json.NewEncoder(w).Encode(mockData)
110	
111		case "/api/transactions", "/api/blocks", "/api/assets":
112			// Return empty array for these endpoints
113			json.NewEncoder(w).Encode([]interface{}{})
114	
115		default:
116			w.WriteHeader(http.StatusInternalServerError)
117			json.NewEncoder(w).Encode(map[string]interface{}{
118				"error":   "Backend unavailable",
119				"message": "Failed to fetch from backend, no mock data available",
120			})
121		}
122	}
123	
124	func (h *Handler) handleObjects(w http.ResponseWriter, r *http.Request) {
125		h.proxyRequest(w, r, "/api/objects")
126	}
127	
128	func (h *Handler) handleTransactions(w http.ResponseWriter, r *http.Request) {
129		h.proxyRequest(w, r, "/api/transactions")
130	}
131	
132	func (h *Handler) handleBlocks(w http.ResponseWriter, r *http.Request) {
133		h.proxyRequest(w, r, "/api/blocks")
134	}
135	
136	func (h *Handler) handleAssets(w http.ResponseWriter, r *http.Request) {
137		h.proxyRequest(w, r, "/api/assets")
138	}
139	
140	func (h *Handler) handleView(w http.ResponseWriter, r *http.Request) {
141		vars := mux.Vars(r)
142		id := vars["id"]
143	
144		if id == "" {
145			http.Error(w, "Invalid or missing object ID", http.StatusBadRequest)
146			return
147		}
148	
149		// First, try to get object data from backend
150		backendURL := h.getBackendURL()
151		objectURL := backendURL + "/api/objects/" + id
152	
153		h.logger.Debug("Fetching object data",
154			zap.String("id", id),
155			zap.String("url", objectURL),
156		)
157	
158		req, err := http.NewRequest("GET", objectURL, nil)
159		if err != nil {
160			h.logger.Error("Failed to create object request", zap.Error(err))
161			http.Error(w, "Internal server error", http.StatusInternalServerError)
162			return
163		}
164	
165		resp, err := h.httpClient.Do(req)
166		if err != nil {
167			h.logger.Error("Failed to fetch object data",
168				zap.String("id", id),
169				zap.Error(err),
170			)
171			http.Error(w, "Failed to fetch object data", http.StatusInternalServerError)
172			return
173		}
174		defer resp.Body.Close()
175	
176		if resp.StatusCode == http.StatusNotFound {
177			http.Error(w, fmt.Sprintf("Object with ID %s not found", id), http.StatusNotFound)
178			return
179		}
180	
181		if resp.StatusCode != http.StatusOK {
182			h.logger.Error("Backend returned error for object",
183				zap.String("id", id),
184				zap.Int("status", resp.StatusCode),
185			)
186			http.Error(w, "Failed to fetch object data", http.StatusInternalServerError)
187			return
188		}
189	
190		// Parse object data
191		var objectData map[string]interface{}
192		if err := json.NewDecoder(resp.Body).Decode(&objectData); err != nil {
193			h.logger.Error("Failed to parse object data", zap.Error(err))
194			http.Error(w, "Invalid object data", http.StatusInternalServerError)
195			return
196		}
197	
198		// Generate HTML viewer
199		h.generateViewerHTML(w, id, objectData)
200	}
