              </Button>
              <Badge variant="secondary">Active</Badge>
              <Button variant="ghost" size="sm" onClick={onClose}>
                <X className="w-4 h-4" />
              </Button>
            </div>
          </div>

          <div className="flex-1 overflow-auto">
            <Tabs defaultValue="terminal" className="h-full">
              <div className="px-6 pt-4">
                <TabsList className="grid w-full grid-cols-3">
                  <TabsTrigger value="terminal">Terminal</TabsTrigger>
                  <TabsTrigger value="workflows">Workflows</TabsTrigger>
                  <TabsTrigger value="tools">Tools</TabsTrigger>
                </TabsList>
              </div>

              <TabsContent value="terminal" className="px-6 pb-6 space-y-4">
                <Card className="knirv-card-gradient">
                  <CardHeader>
                    <CardTitle className="flex items-center space-x-2">
                      <Terminal className="w-5 h-5" />
                      <span>P2P Transport Terminal</span>
                      {isExecuting && <Badge variant="secondary" className="text-xs">running...</Badge>}
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="bg-black rounded-lg p-4 font-mono text-sm">
                      <div className="text-blue-400 space-y-1 max-h-96 overflow-y-auto">
                        {terminalOutput.map((line, index) => (
                          <div key={index}>{line}</div>
                        ))}
                        <div ref={terminalEndRef} />
                      </div>
                      <div className="flex items-center mt-2">
                        <span className="text-blue-400">$ </span>
                        <input
                          type="text"
                          value={currentCommand}
                          onChange={(e) => setCurrentCommand(e.target.value)}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter' && currentCommand.trim() && !isExecuting) {
                              executeCommand(currentCommand.trim());
                            }
                          }}
                          className="flex-1 bg-transparent text-blue-400 outline-none ml-2"
                          placeholder={isExecuting ? 'Executing...' : 'Enter command...'}
                          disabled={isExecuting}
                          autoFocus
                        />
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </TabsContent>

              <TabsContent value="workflows" className="px-6 pb-6 space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {workflowTemplates.map((template) => (
                    <Card key={template.id} className="knirv-card-gradient">
                      <CardHeader className="pb-2">
                        <CardTitle className="flex items-center space-x-2 text-sm">
                          {template.icon}
                          <span>{template.name}</span>
                        </CardTitle>
                        <CardDescription className="text-xs">
                          {template.description}
                        </CardDescription>
                      </CardHeader>
                      <CardContent className="space-y-2">
                        <div className="text-xs text-muted-foreground">
                          Commands: {template.commands.join(', ')}
                        </div>
                        <Button
                          variant="outline"
                          size="sm"
                          className="w-full"
                          disabled={isExecuting}
                          onClick={() => executeCommand(template.commands[0])}
                        >
                          <Play className="w-3 h-3 mr-1" />
                          Execute
                        </Button>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </TabsContent>

              <TabsContent value="tools" className="px-6 pb-6 space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                  <Card className="knirv-card-gradient">
                    <CardHeader className="pb-2">
                      <CardTitle className="flex items-center space-x-2 text-sm">
                        <Users className="w-4 h-4" />
                        <span>Peers {!peersLoading && <span className="text-muted-foreground">({peers.length})</span>}</span>
                      </CardTitle>
                      <CardDescription className="text-xs">
                        {peersLoading ? 'Loading...' : 'Connected peer list'}
                      </CardDescription>
                    </CardHeader>
                    <CardContent className="space-y-1">
                      <Button variant={showPeers ? "default" : "outline"} size="sm" className="w-full" onClick={() => setShowPeers(!showPeers)}>
                        {showPeers ? 'Hide' : 'View'}
                      </Button>
                      {showPeers && (
                        <div className="text-xs font-mono space-y-1 mt-2 max-h-32 overflow-y-auto">
                          {peers.length === 0 ? (
                            <div className="text-muted-foreground">No peers connected</div>
                          ) : peers.map(p => (
                            <div key={p.id} className="flex justify-between">
                              <span className="text-blue-400 truncate">{p.id.slice(0, 12)}</span>
                              <span className="text-muted-foreground ml-2">{p.latency_ms}ms</span>
                            </div>
                          ))}
                        </div>
                      )}
                    </CardContent>
                  </Card>

                  <Card className="knirv-card-gradient">
                    <CardHeader className="pb-2">
                      <CardTitle className="flex items-center space-x-2 text-sm">
                        <Radio className="w-4 h-4" />
                        <span>Relay</span>
                      </CardTitle>
                      <CardDescription className="text-xs">
                        TURN relay status
                      </CardDescription>
                    </CardHeader>
                    <CardContent>
                      <Button variant={showRelay ? "default" : "outline"} size="sm" className="w-full" onClick={() => setShowRelay(!showRelay)}>
                        {showRelay ? 'Hide' : 'View'}
                      </Button>
                    </CardContent>
                  </Card>

                  <Card className="knirv-card-gradient">
                    <CardHeader className="pb-2">
                      <CardTitle className="flex items-center space-x-2 text-sm">
                        <Globe className="w-4 h-4" />
                        <span>NAT</span>
                      </CardTitle>
                      <CardDescription className="text-xs">
                        NAT traversal config
                      </CardDescription>
                    </CardHeader>
                    <CardContent>
                      <Button variant={showNAT ? "default" : "outline"} size="sm" className="w-full" onClick={() => setShowNAT(!showNAT)}>
                        {showNAT ? 'Hide' : 'Configure'}
                      </Button>
                    </CardContent>
                  </Card>

                  <Card className="knirv-card-gradient">
                    <CardHeader className="pb-2">
                      <CardTitle className="flex items-center space-x-2 text-sm">
                        <BarChart3 className="w-4 h-4" />
                        <span>Monitor</span>
                      </CardTitle>
                      <CardDescription className="text-xs">
                        Network metrics
                      </CardDescription>
                    </CardHeader>
                    <CardContent>
                      <Button variant="outline" size="sm" className="w-full" onClick={openWebGui}>
                        Open
                      </Button>
                    </CardContent>
                  </Card>
                </div>
              </TabsContent>
            </Tabs>
          </div>
        </div>
      </div>
    </div>
  );
}

package embedded

import (
	"context"
	"embed"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/KNIRV/KNIRV_NETWORK/KNIRVGATEWAY/internal/config"
	"github.com/KNIRV/KNIRV_NETWORK/KNIRVGATEWAY/internal/runtime"
	"github.com/KNIRV/KNIRV_NETWORK/KNIRVGATEWAY/internal/server"
	"go.uber.org/zap"
)

// Embed all service directories (excluding node_modules, build artifacts)
//
//go:embed all:webgui
var WebGUIFS embed.FS

// The standalone gateway serves network-website from the source tree instead of embedding it.
// KNIRVSERVER's packaged gateway keeps its own embedded copy in pkg/knirvgateway.
var NetworkWebsiteFS embed.FS

// GatewayConfig represents the configuration for the embedded gateway runner.
// The oracle itself has moved to KNIRVSERVER and is no longer managed here.
type GatewayConfig struct {
	Port            int    `json:"port"`
	ChainID         string `json:"chainID"`
	Mode            string `json:"mode"`
	AutoOpenBrowser bool   `json:"autoOpenBrowser"`
}

// DefaultConfig returns a default configuration for the embedded gateway runner.
func DefaultConfig() *GatewayConfig {
	return &GatewayConfig{
		Port:            8080,
		ChainID:         "testnet",
		Mode:            "oracle_nest",
		AutoOpenBrowser: false,
	}
}

type Gateway struct {
	cfg     *GatewayConfig
	logger  *zap.Logger
	runtime *runtime.Runtime
	server  *server.Server
	stopCh  chan struct{}
}

// NewGateway creates a new gateway runner.
func NewGateway(cfg *GatewayConfig, logger *zap.Logger) (*Gateway, error) {
	if cfg == nil {
		cfg = DefaultConfig()
	}

	if logger == nil {
		var err error
		logger, err = zap.NewProduction()
		if err != nil {
			return nil, err
		}
	}

	rt, err := runtime.NewRuntime(logger, WebGUIFS, NetworkWebsiteFS, nil)
	if err != nil {
		return nil, err
	}

	return &Gateway{
		cfg:     cfg,
		logger:  logger,
		runtime: rt,
		stopCh:  make(chan struct{}),
	}, nil
}

// Start initialises and starts the  gateway.
func (g *Gateway) Start() error {
	g.logger.Info("Starting KNIRVGATEWAY",
		zap.String("mode", g.cfg.Mode),
		zap.Int("port", g.cfg.Port),
		zap.String("chainID", g.cfg.ChainID),
	)

	if err := g.runtime.Setup(); err != nil {
		return err
	}

	os.Setenv("KNIRV_MODE", g.cfg.Mode)
	os.Setenv("CHAIN_ID", g.cfg.ChainID)

	coreCfg, err := config.Load()
	if err != nil {
		return err
	}

	g.server, err = server.New(coreCfg, g.runtime.GetWebGUIStaticPath(), g.runtime.GetNetworkWebsitePath(), g.logger)
	if err != nil {
		return err
	}

	go func() {
		g.logger.Info("Starting HTTP server", zap.Int("port", g.cfg.Port))
		if err := g.server.Start(); err != nil {
			g.logger.Fatal("Server failed", zap.Error(err))
		}
	}()

	time.Sleep(2 * time.Second)

	g.logger.Info("Embedded KNIRVGATEWAY started successfully")

	go g.handleSignals()

	return nil
}

func (g *Gateway) handleSignals() {
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)

	select {
	case <-sigChan:
		g.logger.Info("Received shutdown signal")
		g.Stop()
	case <-g.stopCh:
		g.logger.Info("Received stop signal")
	}
}

// Stop gracefully stops the embedded gateway.
func (g *Gateway) Stop() error {
	g.logger.Info("Stopping embedded KNIRVGATEWAY")

	close(g.stopCh)

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	if g.server != nil {
		if err := g.server.Stop(ctx); err != nil {
			g.logger.Error("Error stopping server", zap.Error(err))
		}
	}

	if err := g.runtime.Cleanup(); err != nil {
		g.logger.Error("Failed to cleanup runtime", zap.Error(err))
	}

	g.logger.Info("Embedded KNIRVGATEWAY stopped")
	return nil
}

// GetRuntime returns the runtime instance.
func (g *Gateway) GetRuntime() *runtime.Runtime {
	return g.runtime
}

// GetServer returns the server instance.
func (g *Gateway) GetServer() *server.Server {
	return g.server
}

// GetPort returns the configured port.
func (g *Gateway) GetPort() int {
	return g.cfg.Port
}

// GetChainID returns the configured chain ID.
func (g *Gateway) GetChainID() string {
	return g.cfg.ChainID
}

// IsRunning returns true if the gateway is running.
func (g *Gateway) IsRunning() bool {
	select {
	case <-g.stopCh:
		return false
	default:
		return true
	}
}

